const D = { scale:1, density:.55, energy:.55, speed:1, drape:.5, hue:212, x:.5, y:.5, style:'steel', seed:0, alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const t = K.t, sty = P.style, en = P.energy;
const hsh = i => { const s = Math.sin(i*127.1 + P.seed*311.7)*43758.5453; return s - Math.floor(s); };
const C = Math.max(6, Math.min(16, Math.round(7 + P.density*9)));
const Rr = Math.max(7, Math.min(18, Math.round((8 + P.density*10) * (height/width) * 1.3 )));
const colStep = width/(C-1), rowStep = height/(Rr-1);
const rw = colStep*0.60*(0.7+0.5*P.scale), rh = rowStep*0.62*(0.7+0.5*P.scale);
const tw = Math.max(2, colStep*(0.13+0.06*en));
const tiltB = 0.34;
const drapeA = (0.10 + 0.55*P.drape) * rowStep;
const rate = 0.6 + P.speed*0.9;
const bass = Math.min(0.5, A.bass*0.6);
const lightX = 0.5 + 0.42*Math.sin(t*0.17) + 0.12*Math.sin(t*0.41+2.0); // sheen band travels

let bg0=220,bg1=30,bg2=10;
if (sty==='brass'){bg0=32;bg1=34;bg2=11;}
else if (sty==='blackened'){bg0=222;bg1=26;bg2=7;}
else if (sty==='blueprint'){bg0=214;bg1=58;bg2=18;}
else if (sty==='wire'){bg0=224;bg1=40;bg2=6;}
background(bg0,bg1,bg2);

let met=[214,10,58,96]; // hue,sat,bodyV,hiV
if (sty==='brass') met=[44,55,52,95];
else if (sty==='blackened') met=[220,22,30,66];

function ring(cx,cy,tilt,over,c,r){
  const dip = drapeA*Math.sin(cx*0.011 - t*rate + cy*0.006) + drapeA*0.5*Math.sin(cy*0.017 + t*0.7);
  const yy = cy + dip;
  const sheen = Math.max(0, 1 - Math.abs(cx/width - lightX)*3.0);
  push(); translate(cx, yy); rotate(tilt);
  noFill();
  if (sty==='wire'){
    blendMode(ADD);
    stroke((P.hue+18*sheen)%360, 45, 34+50*sheen, 70*(P.alpha/100)); strokeWeight(1.3+1.2*sheen);
    ellipse(0,0,rw*2,rh*2);
    blendMode(BLEND); pop(); return;
  }
  if (sty==='blueprint'){
    stroke(200,64,34,P.alpha); strokeWeight(tw*0.8); ellipse(0,0,rw*2,rh*2);
    stroke(192,22,90,P.alpha*0.85); strokeWeight(tw*0.24); ellipse(0,0,rw*2,rh*2);
    pop(); return;
  }
  // metallic torus ring
  stroke(met[0], met[1]+8, met[2]*0.35, P.alpha); strokeWeight(tw*1.25); ellipse(0,0,rw*2,rh*2); // casing
  stroke(met[0], met[1], met[2]*(0.75+0.35*sheen)+8*bass, P.alpha); strokeWeight(tw); ellipse(0,0,rw*2,rh*2); // body
  stroke((met[0]+6)%360, met[1]*0.5, Math.min(100, met[3]*(0.55+0.6*sheen)+12*bass), P.alpha); strokeWeight(tw*0.4);
  arc(-tw*0.2,-tw*0.2, rw*2, rh*2, Math.PI*1.05, Math.PI*1.95); // highlight (upper-left)
  pop();
}

// pass A: all rings shingled top->bottom (lower occludes upper => interlock)
for (let r=0;r<Rr;r++){
  for (let c=0;c<C;c++){
    const cx = c*colStep + (r%2)*colStep*0.5 - colStep*0.25;
    const cy = r*rowStep;
    const tilt = tiltB*((c%2)?1:-1);
    ring(cx,cy,tilt,false,c,r);
  }
}
// pass B: over-set (even columns) redraw top arc so they weave over the row above
if (sty!=='wire' && sty!=='blueprint'){
  for (let r=0;r<Rr;r++){
    for (let c=0;c<C;c+=2){
      const cx = c*colStep + (r%2)*colStep*0.5 - colStep*0.25;
      const cy = r*rowStep;
      const dip = drapeA*Math.sin(cx*0.011 - t*rate + cy*0.006) + drapeA*0.5*Math.sin(cy*0.017 + t*0.7);
      const sheen = Math.max(0, 1 - Math.abs(cx/width - lightX)*3.0);
      const tilt = tiltB*((c%2)?1:-1);
      drawingContext.shadowBlur = tw*0.7; drawingContext.shadowColor='rgba(0,0,0,0.4)';
      push(); translate(cx, cy+dip); rotate(tilt); noFill();
      stroke(met[0], met[1], met[2]*(0.78+0.35*sheen), P.alpha); strokeWeight(tw);
      arc(0,0,rw*2,rh*2, Math.PI, Math.PI*2);
      drawingContext.shadowBlur = 0;
      stroke((met[0]+6)%360, met[1]*0.5, Math.min(100, met[3]*(0.6+0.55*sheen)), P.alpha); strokeWeight(tw*0.4);
      arc(-tw*0.2,-tw*0.2, rw*2, rh*2, Math.PI*1.05, Math.PI*1.95);
      pop();
    }
  }
}
drawingContext.shadowBlur = 0;
blendMode(BLEND);
